import networkx as nx
import itertools

g = nx.Graph()
g.add_edges_from([(1,4), (1,2), (1,9), (0,3)])
for i in range(14):
    g.add_node(i)

for r in range(2, 5):
    for combination in itertools.combinations(range(14), r):
        if len(combination) == 2:
            if (combination[0], combination[1]) not in g.edges:
                g.add_edge(combination[0], combination[1])
        else:
            if all((combination[i], combination[j]) in g.edges for i in range(len(combination)) for j in range(i+1, len(combination))):
                if len(combination) > 4:
                    g.remove_edges_from([(combination[i], combination[j]) for i in range(len(combination)) for j in range(i+1, len(combination))])

for node in g.nodes:
    if g.degree(node) == 0:
        g.add_edge(node, 0)

print(g.edges)
